## 修改清单

所有改动在 `terminal-card-04.ts` 一个文件内：

### `activate()` — 加复用分支（在 `buildCardLayout` 之前插入）

```typescript
// 紧缩→展开：复用已有 Terminal，不重开 PTY
if (card.meta._term as Terminal) {
  const term = card.meta._term as Terminal;
  const fit = card.meta._fit as FitAddon;
  const { bodyEl } = buildCardLayout(contentEl, '> 终端 ' + card.meta.terminalId, card.accents.color1, card.accents.color2);
  const termEl = document.createElement('div');
  termEl.style.cssText = 'flex:1;overflow:hidden';
  bodyEl.appendChild(termEl);
  term.open(termEl);
  const xtermEl = termEl.querySelector('.xterm') as HTMLElement;
  if (xtermEl) { xtermEl.style.touchAction = 'none'; _termMap.set(xtermEl, term); }
  fit.fit();
  // 重建 ResizeObserver
  const observer = new ResizeObserver(() => { ... });
  observer.observe(termEl);
  card.meta._observer = observer;
  return;  // 不发送 terminal-open，PTY 还在跑
}
```

### `deactivate()` — 区分 dismiss / compact

```typescript
if (reason === 'dismiss') {
  // 关闭：销毁一切
  wsChannel.sendMessage('terminal-close', ...);
  wsChannel.offMessage('terminal-output', ...);
  wsChannel.offMessage('terminal-exit', ...);
  _termMap.delete(...);
  term.dispose();
  cardRegistry.freeId('card03', ...);
  contentEl.innerHTML = '';
} else {
  // 紧缩：保留 Terminal 和 WS 监听器，只清理 DOM
  if (_observer) _observer.disconnect();
  if (_xtermEl) _termMap.delete(_xtermEl);
  contentEl.innerHTML = '';
}
```

### 效果

| 操作 | 行为 |
|------|------|
| 紧缩 → 展开 | Terminal 实例不变，PTY 不重开，内容原样保留 |
| 关闭 → 重开 | 全新 Terminal + 全新 PTY 会话 |

